const RELAY_API_BASE = 'https://api.relayfi.com'; // confirm exact base URL with Relay
const SCRIPT_PROPERTIES = PropertiesService.getScriptProperties();

// Script Properties REQUIRED:
// RELAY_API_KEY = <your_api_key>

const SHEETS = {
  MASTER: 'Account_Master',
  LIVE: 'Cash_Position_Live',
  HISTORY: 'Cash_History'
};

/**************************************
 * ENTRY POINT (TIME-DRIVEN TRIGGER)
 **************************************/
function updateRelayBalances() {
  try {
    const accounts = getRelayAccounts();
    const balances = getBalancesByAccount(accounts);

    updateLiveSheet(balances);
    appendHistory(balances);

    Logger.log('Relay balances updated successfully');
  } catch (error) {
    Logger.log('ERROR: ' + error.message);
    notifyFailure(error);
    throw error;
  }
}

/**************************************
 * RELAY API FUNCTIONS
 **************************************/
function getRelayAccounts() {
  const response = relayRequest('/accounts');
  if (!response.accounts) throw new Error('Invalid accounts response');
  return response.accounts;
}

function getBalancesByAccount(accounts) {
  const results = [];

  accounts.forEach(account => {
    const balanceResponse = relayRequest(`/accounts/${account.id}/balances`);

    results.push({
      accountId: account.id,
      accountName: account.name,
      availableBalance: balanceResponse.available_balance,
      ledgerBalance: balanceResponse.ledger_balance,
      currency: balanceResponse.currency,
      timestamp: new Date()
    });
  });

  return results;
}

function relayRequest(endpoint) {
  const apiKey = SCRIPT_PROPERTIES.getProperty('RELAY_API_KEY');
  if (!apiKey) throw new Error('Missing Relay API Key');

  const options = {
    method: 'get',
    headers: {
      Authorization: 'Bearer ' + apiKey,
      'Content-Type': 'application/json'
    },
    muteHttpExceptions: true
  };

  const response = UrlFetchApp.fetch(RELAY_API_BASE + endpoint, options);
  const status = response.getResponseCode();
  const body = response.getContentText();

  if (status >= 300) {
    throw new Error(`Relay API error ${status}: ${body}`);
  }

  return JSON.parse(body);
}

/**************************************
 * GOOGLE SHEETS FUNCTIONS
 **************************************/
function updateLiveSheet(balances) {
  const sheet = SpreadsheetApp.getActive().getSheetByName(SHEETS.LIVE);
  if (!sheet) throw new Error('Missing Cash_Position_Live sheet');

  const data = sheet.getDataRange().getValues();
  const headers = data.shift();

  const colIndex = indexColumns(headers);

  balances.forEach(row => {
    const matchRow = data.findIndex(r => r[colIndex.accountId] === row.accountId);

    if (matchRow === -1) return; // ignore unknown accounts

    const sheetRow = matchRow + 2;

    sheet.getRange(sheetRow, colIndex.availableBalance + 1).setValue(row.availableBalance);
    sheet.getRange(sheetRow, colIndex.ledgerBalance + 1).setValue(row.ledgerBalance);
    sheet.getRange(sheetRow, colIndex.lastUpdated + 1).setValue(row.timestamp);
  });
}

function appendHistory(balances) {
  const sheet = SpreadsheetApp.getActive().getSheetByName(SHEETS.HISTORY);
  if (!sheet) return; // optional sheet

  const rows = balances.map(b => [
    b.timestamp,
    b.accountId,
    b.accountName,
    b.availableBalance,
    b.ledgerBalance,
    b.currency
  ]);

  sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
}

function indexColumns(headers) {
  return {
    accountId: headers.indexOf('Account ID'),
    availableBalance: headers.indexOf('Available Balance'),
    ledgerBalance: headers.indexOf('Ledger Balance'),
    lastUpdated: headers.indexOf('Last Updated')
  };
}

/**************************************
 * ALERTING
 **************************************/
function notifyFailure(error) {
  const email = Session.getActiveUser().getEmail();
  MailApp.sendEmail({
    to: email,
    subject: 'Relay Balance Automation FAILED',
    body: 'Error details:\n' + error.message
  });
}

/**************************************
 * ONE-TIME SETUP HELPERS
 **************************************/
function setRelayApiKey() {
  SCRIPT_PROPERTIES.setProperty('RELAY_API_KEY', 'PASTE_API_KEY_HERE');
}

